class FakePaxyo:
    """Stand-in for PaxyoClient with a fat balance.

    recent/schedules/due let tests seed the server-side memory: the
    user's last orders, active repeating orders, and due schedules.
    """

    RECENT_ORDER = {
        "id": 1827, "service_id": 1001,
        "service_name": "Instagram Followers | Fast",
        "link": "https://instagram.com/p/x", "quantity": 1000,
        "charge": 42.0, "status": "pending",
        "created_at": "2026-11-13T10:00:00Z",
    }

    DEPOSIT = {
        "id": "dep-1", "amount": 10, "method": "telebirr",
        "phone": "25199387383", "status": "pending",
        "created_at": "2026-11-13T11:00:00Z",
    }

    def __init__(self, balance=1000.0, recent=None, schedules=None, due=None,
                 deposit_none=False, deposit_error=None,
                 deposit_error_status=400,
                 deposits=None, deposits_none=False, status="pending",
                 session=None, delayed=None, delayed_due=None,
                 delayed_none=False, claim_ok=True,
                 services=None, status_by_order=None, admin_stats=None,
                 my_referral=None, referral_error=None,
                 cancel_refund_result=None, cancel_refund_error=None,
                 next_order_ids=None, traits=None,
                 promo_codes=None, promo_none=False,
                 promo_redeem_result=None, promo_redeem_none=False,
                 promo_error=None, report_none=False, report_error=None,
                 ratings=None, ratings_none=False, rate_none=False,
                 rate_error=None, rate_already=False,
                 refill_result=None, refill_none=False,
                 refill_error=None,
                 price_snapshot=None, price_snapshot_none=False,
                 price_snapshot_error=None, price_snapshot_save_none=False,
                 price_snapshot_save_error=None, loyalty_result=None,
                 loyalty_error=None, feedback_asked_result=None,
                 feedback_asked_error=None, feedback_mark_none=False,
                 cancel_order_result=None, cancel_order_none=False,
                 cancel_order_error=None, partial_result=None,
                 partial_none=False, partial_error=None,
                 fraud_flags=None, fraud_none=False,
                 order_records=None, order_status_none=False):
        self._balance = balance
        self._status = status
        self._status_by_order = dict(status_by_order or {})
        self._admin_stats = admin_stats
        self.admin_stats_calls = 0
        self._my_referral = my_referral
        self._referral_error = referral_error
        self.referrals_recorded = []
        self._services = list(services) if services is not None else SAMPLE_SERVICES
        self.orders_created = []
        self.order_keys = []
        # Stall rescue (15 Nov 2026): a seeded refund for
        # cancel_refund (None by default — the endpoint is not live
        # yet, so the real client returns None on its 404), a
        # record of every cancel-refund call, and optional ids for
        # orders create_order returns (1827 by default, so existing
        # tests keep their order id).
        self._cancel_refund_result = cancel_refund_result
        self._cancel_refund_error = cancel_refund_error
        self._next_order_ids = list(next_order_ids or [])
        self.cancel_refund_calls = []
        # Round 3 (15 Nov 2026): cancel order / partial refund /
        # fraud watch. cancel_order_none / partial_none mirror the
        # real client's 404 (endpoint not live yet); _error=409
        # returns the refusal passthrough (ok:false + the server's
        # reason); any other status raises the HTTP error the real
        # client raises. fraud_flags=None (default) returns an
        # empty flags list; fraud_none=True returns None (404).
        self._cancel_order_result = cancel_order_result
        self._cancel_order_none = cancel_order_none
        self._cancel_order_error = cancel_order_error
        self.cancel_order_calls = []
        self._partial_result = partial_result
        self._partial_none = partial_none
        self._partial_error = partial_error
        self.partial_refund_calls = []
        self._fraud_flags = fraud_flags
        self._fraud_none = fraud_none
        self.fraud_watch_calls = 0
        # Round 3 (15 Nov 2026): full order records for
        # order_status (cancel in chat needs service/total), and a
        # 404 mode (order_status_none) mirroring the real client's
        # None-on-404 for an unknown order id.
        self._order_records = dict(order_records or {})
        self._order_status_none = order_status_none
        self._services = list(services) if services is not None else SAMPLE_SERVICES
        self.orders_created = []
        self.order_keys = []
        self._recent = list(recent) if recent is not None else []
        self._schedules = list(schedules) if schedules is not None else []
        self._due = list(due) if due is not None else []
        self.recurring_created = []
        self.recurring_cancelled = []
        self.recurring_paused = []
        self.recurring_ran = []
        self.deposits_created = []
        self._deposit_none = deposit_none
        self._deposit_error = deposit_error
        self._deposit_error_status = deposit_error_status
        self._deposits = list(deposits) if deposits is not None else []
        self._deposits_none = deposits_none
        self.deposit_status_checked = []
        # Session store (smart-loop round 1): a seeded session for
        # load_session, and a record of every save / confusion log.
        self._session = session
        self.session_loads = []
        self.sessions_saved = []
        self.confusions_logged = []
        # Per-user traits (feature 5, 15 Nov 2026): seeded traits
        # for load_traits (None = nothing stored yet, like the real
        # client's 404), and a record of every save / load / clear.
        self._traits = dict(traits) if traits is not None else None
        self.traits_saved = []
        self.traits_loads = []
        self.traits_cleared = []
        # One-time delayed orders (14 Nov 2026): a seeded list for
        # list_delayed_orders, due rows for due_delayed_orders, and
        # a record of every create / cancel / claim / finish.
        self._delayed = list(delayed) if delayed is not None else []
        self._delayed_due = list(delayed_due) if delayed_due is not None else []
        self._delayed_none = delayed_none
        self._claim_ok = claim_ok
        self._delayed_next_id = 101
        self.delayed_created = []
        self.delayed_cancelled = []
        self.delayed_claims = []
        self.delayed_finished = []
        # Promo codes (ideas batch 2, feature 1, 15 Nov 2026):
        # promo_codes maps an uppercased code to its validate
        # record; an unmapped code gets the "does not exist"
        # record. promo_none=True returns None from validate and
        # redeem (the real client does that on a 404: endpoint not
        # live yet). promo_error=<status> raises the HTTP error the
        # real client raises on a non-404 failure.
        self._promo_codes = dict(promo_codes or {})
        self._promo_none = promo_none
        self._promo_redeem_result = promo_redeem_result
        self._promo_redeem_none = promo_redeem_none
        self._promo_error = promo_error
        self.promo_validates = []
        self.promo_redeems = []
        # Report a problem (ideas batch 2, feature 2, 15 Nov 2026):
        # reports_filed records every report (telegram_id, order_id,
        # message). report_none=True returns None (the real client
        # does that on a 404: endpoint not live yet, or the named
        # order is not this user's). report_error=<status> raises
        # the HTTP error the real client raises on a non-404
        # failure.
        self._report_none = report_none
        self._report_error = report_error
        self.reports_filed = []
        # Rate your order (ideas batch 2, feature 3, 15 Nov 2026):
        # ratings maps a service id (str) to {"good": n, "bad": n}
        # for service_ratings; unknown ids read 0/0. rate_none=True
        # returns None from rate_order (404: endpoint not live yet);
        # rate_error=<status> raises the HTTP error the real client
        # raises on a non-404 failure; rate_already=True returns the
        # already-rated 409 passthrough for every tap. ratings_none
        # returns None from service_ratings (404: endpoint not live).
        self._ratings = dict(ratings or {})
        self._ratings_none = ratings_none
        self._rate_none = rate_none
        self._rate_error = rate_error
        self._rate_already = rate_already
        self.ratings_filed = []
        self.ratings_calls = []
        # Refill in chat (15 Nov 2026, feature 3): a seeded refill
        # result for refill_order (None by default — the endpoint is
        # not live yet, so the real client returns None on its 404),
        # and a record of every refill call. refill_none=True
        # returns None (404: endpoint not live yet);
        # refill_error=<status> raises the HTTP error the real
        # client raises on a non-404 failure (409 not refillable
        # with the provider's reason, 501 refill action not
        # offered — the real client passes both bodies through as
        # {"ok": false, ...}, so this mirror returns the same dict
        # instead of raising for those two).
        self._refill_result = refill_result
        self._refill_none = refill_none
        self._refill_error = refill_error
        self.refill_calls = []
        # Provider price-change watch (feature 6, 15 Nov 2026):
        # price_snapshot seeds the stored snapshot ({} by default —
        # nothing stored yet, so the bot bootstraps); the save
        # REPLACES it, mirroring the server. price_snapshot_none
        # returns None from get (404: endpoint not live yet);
        # price_snapshot_error=<status> raises the HTTP error the
        # real client raises on a non-404 GET failure;
        # price_snapshot_save_none / _save_error do the same for
        # the POST. services_refresh_count is the catalogue
        # refresh counter the real client exposes — tests set it
        # by hand to simulate a real fetch.
        self._price_snapshot = dict(price_snapshot or {})
        self._price_snapshot_none = price_snapshot_none
        self._price_snapshot_error = price_snapshot_error
        self._price_snapshot_save_none = price_snapshot_save_none
        self._price_snapshot_save_error = price_snapshot_save_error
        self.price_snapshot_saved = []
        self.price_snapshot_calls = 0
        self.services_refresh_count = 0
        # Loyalty bonus (feature 9, 15 Nov 2026): loyalty_result
        # seeds the POST /loyalty/check reply (None by default —
        # the endpoint is not live yet, so the real client returns
        # None on its 404). loyalty_error=<status> raises the HTTP
        # error the real client raises on a non-404 failure.
