        bot._USUAL_COUNTS.clear()
        bot._TONE_SIGNALS.clear()
        bot._TRAITS_FROM_SERVER.clear()
        bot._LAST_TRAITS_SAVE.clear()
        bot.CANCELLED_DRAFT.clear()
        bot.LAST_ORDER.clear()
