class TestTrustAndPolicy(unittest.IsolatedAsyncioTestCase):
    """Safety, refunds, geo-targeting, free samples, haggling."""

    def setUp(self):
        bot.PENDING.clear()
        bot.PENDING_REFILL.clear()
        bot.USER_TRAITS.clear()
        bot.USUAL_SERVICE.clear()
        bot._USUAL_COUNTS.clear()
