    async def test_first_off_topic_general_answer_mocked(self):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("off_topic")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(
                return_value="The capital of France is Paris."
            ),
        ), mock.patch("bot.speak_reply"):
            await bot.handle_order_text(
                update, None, "Who will win the football tonight?"
            )
        self.assertIn("Paris", msg.text_sent[0])
        self.assertIn("what would you like to order?", msg.text_sent[0].lower())

    async def test_off_topic_questions_always_answered(self):
        # Widened 14 Nov 2026 (owner): a real question always gets
        # a free AI answer plus the steer-back line — never the
        # canned deflection, however many turns it takes. (Was:
        # the third off-topic turn steered back with no answer.)
        # The Telegram post-link question used to be the third
        # question here; it is now a deterministic answer (owner
        # fix round, 14 Nov 2026), so a different off-topic
        # question takes its place.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("off_topic")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(return_value="The capital of France is Paris."),
        ), mock.patch("bot.speak_reply"):
            for text in (
                "Who will win the football tonight?",
                "What is the weather like?",
                "What is the capital of Spain?",
            ):
                await bot.handle_order_text(update, None, text)
        self.assertEqual(len(msg.text_sent), 3)
        for reply in msg.text_sent:
            self.assertIn("Paris", reply)
            self.assertIn("what would you like to order?", reply.lower())
        self.assertNotIn("Paris", bot.t("off_topic_steer", "en"))

    async def test_third_off_topic_statement_steers_back(self):
        # Only non-question chit-chat is capped: the first two
        # turns get a general answer plus a nudge, the third
        # steers back with no answer.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(return_value=intent_of("off_topic")),
        ), mock.patch("bot.paxyo", FakePaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(return_value="The capital of France is Paris."),
        ), mock.patch("bot.speak_reply"):
            for text in (
                "Tell me a story.",
                "Sing me a song.",
                "Make me laugh.",
            ):
                await bot.handle_order_text(update, None, text)
        self.assertEqual(len(msg.text_sent), 3)
        self.assertIn("Paris", msg.text_sent[0])
        self.assertIn("Paris", msg.text_sent[1])
        self.assertEqual(msg.text_sent[2], bot.t("off_topic_steer", "en"))
        self.assertNotIn("Paris", msg.text_sent[2])

    async def test_order_resets_off_topic_counter(self):
        msg = FakeMessage()
        update = FakeUpdate(msg)
        intents = [
            intent_of("off_topic"),
            intent_of("off_topic"),
            intent_of("order", platform="tiktok",
                      service_hint="tiktok views",
                      link="https://vt.tiktok.com/ZSpQWTSmH/",
                      quantity=1000),
            intent_of("off_topic"),
        ]
        with mock.patch(
            "bot.extract_intent", new=mock.AsyncMock(side_effect=intents)
        ), mock.patch("bot.paxyo", TikTokPaxyo()), mock.patch(
            "bot.ai_generate",
            new=mock.AsyncMock(return_value="The capital of France is Paris."),
        ), mock.patch("bot.speak_reply"):
            for text in (
                "Who will win the football tonight?",
                "What is the weather like?",
                "I want 1000 tiktok views https://vt.tiktok.com/ZSpQWTSmH/",
                "Tell me a story.",
            ):
                await bot.handle_order_text(update, None, text)
        # The order reset the counter, so the last off-topic turn
        # gets a general answer again, not the steer.
        self.assertIn("Paris", msg.text_sent[3])

