class TestPausedServices(unittest.IsolatedAsyncioTestCase):
    """Paused services (owner, 14 Nov 2026): cheap premium
    subscriptions (CapCut Pro, Canva Pro, ...) and SMS OTP
    verification are paused. Asked for any of them, the bot says so
    in one short line — no date, no price, never "available", never
    a social-media service instead, and never volunteered."""

    def setUp(self):
        for store in (
            bot.USER_TRAITS, bot.USUAL_SERVICE,
            bot._USUAL_COUNTS, bot._TONE_SIGNALS,
            bot._TRAITS_FROM_SERVER, bot._LAST_TRAITS_SAVE,
            bot.PENDING, bot.PENDING_REFILL, bot.LAST_ORDER, bot.PARTIAL,
            bot.PENDING_RECURRING, bot.RECURRING_DRAFT,
            bot.DEPOSIT_DRAFT, bot.PENDING_DEPOSIT, bot.LAST_DEPOSIT,
            bot.PENDING_BATCH, bot.SPLIT_DRAFT, bot.FASTEST_FALLBACK,
            bot.BUDGET_OPTIONS, bot.SEEN_UPDATES, bot.RECEIPT_OFFER,
            bot.OFF_TOPIC_COUNT, bot.OFFENSE_COUNT, bot.HUMOR_INDEX,
            bot.CANCELLED_DRAFT,
        ):
            store.clear()
        bot.CHAT_HISTORY.clear()
        bot._CHAT_HISTORY_LOADED = False
        self._history_file = os.path.join(
            tempfile.gettempdir(), "paxyo-test-chat-history.json"
        )
        if os.path.exists(self._history_file):
            os.unlink(self._history_file)
        self._history_patch = mock.patch.object(
            bot, "CHAT_HISTORY_FILE", self._history_file
        )
        self._history_patch.start()
        bot._LAST_HISTORY_SAVE = 0.0

    def tearDown(self):
        self._history_patch.stop()
        for store in (
            bot.USER_TRAITS, bot.USUAL_SERVICE,
            bot._USUAL_COUNTS, bot._TONE_SIGNALS,
            bot._TRAITS_FROM_SERVER, bot._LAST_TRAITS_SAVE,
            bot.PENDING, bot.PENDING_REFILL, bot.LAST_ORDER, bot.PARTIAL,
            bot.PENDING_RECURRING, bot.RECURRING_DRAFT,
            bot.DEPOSIT_DRAFT, bot.PENDING_DEPOSIT, bot.LAST_DEPOSIT,
            bot.PENDING_BATCH, bot.SPLIT_DRAFT, bot.FASTEST_FALLBACK,
            bot.BUDGET_OPTIONS, bot.SEEN_UPDATES, bot.RECEIPT_OFFER,
            bot.OFF_TOPIC_COUNT, bot.OFFENSE_COUNT, bot.HUMOR_INDEX,
            bot.CANCELLED_DRAFT,
        ):
            store.clear()
        bot.CHAT_HISTORY.clear()
        bot._CHAT_HISTORY_LOADED = False
        if os.path.exists(self._history_file):
            os.unlink(self._history_file)

    async def _send(self, text, intent, paxyo=None, ai_reply=_UNSET):
        from contextlib import ExitStack
        msg = FakeMessage()
        update = FakeUpdate(msg)
        patches = [
            mock.patch(
                "bot.extract_intent",
                new=mock.AsyncMock(return_value=intent),
            ),
            mock.patch("bot.paxyo", paxyo or FakePaxyo()),
            mock.patch("bot.speak_reply"),
        ]
        if ai_reply is not _UNSET:
            patches.append(mock.patch(
                "bot.ai_generate",
                new=mock.AsyncMock(return_value=ai_reply),
            ))
        with ExitStack() as stack:
            for patch in patches:
                stack.enter_context(patch)
            await bot.handle_order_text(update, None, text)
        return msg

    async def _send_local(self, text, paxyo=None):
        # intent=None: the local guard must answer without Gemini —
        # extract_intent raises if it is ever called.
        msg = FakeMessage()
        update = FakeUpdate(msg)
        with mock.patch(
            "bot.extract_intent",
            new=mock.AsyncMock(
                side_effect=AssertionError("extract_intent must not be called")
            ),
        ), mock.patch("bot.paxyo", paxyo or FakePaxyo()), \
             mock.patch("bot.speak_reply"):
            await bot.handle_order_text(update, None, text)
        return msg

    def test_prompt_has_paused_services_intent(self):
        self.assertIn('"paused_services"', bot.SYSTEM_PROMPT)
        self.assertIn("CapCut Pro", bot.SYSTEM_PROMPT)
        self.assertIn("Canva Pro", bot.SYSTEM_PROMPT)
        self.assertIn("OTP", bot.SYSTEM_PROMPT)

    async def test_capcut_pro_local(self):
        msg = await self._send_local("I want CapCut Pro")
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_canva_pro_local(self):
        msg = await self._send_local("do you sell Canva Pro")
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_generic_premium_subscriptions_local(self):
        msg = await self._send_local(
            "do you sell cheap premium subscriptions"
        )
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_netflix_premium_local(self):
        msg = await self._send_local("can I get Netflix premium")
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_spotify_premium_local(self):
        msg = await self._send_local("can I get Spotify premium")
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_sms_otp_local(self):
        msg = await self._send_local("I need SMS OTP verification")
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_otp_number_local(self):
        msg = await self._send_local("OTP number for verification")
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_would_like_capcut_local(self):
        # The verb "like" is not the metric "likes": the guard
        # must still fire.
        msg = await self._send_local("I would like CapCut Pro")
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_paused_services_intent_routed(self):
        msg = await self._send(
            "I want CapCut Pro", intent_of("paused_services")
        )
        self.assertEqual(msg.text_sent, [bot.t("paused_services", "en")])

    async def test_paused_repeated_is_same_short_line(self):
        first = await self._send(
            "I want CapCut Pro", intent_of("paused_services")
        )
        second = await self._send(
            "do you sell Canva Pro", intent_of("paused_services")
        )
        self.assertEqual(first.text_sent, [bot.t("paused_services", "en")])
        self.assertEqual(second.text_sent, [bot.t("paused_services", "en")])

    def test_paused_answer_has_no_date_or_price(self):
        reply = bot.t("paused_services", "en")
        self.assertIn("paused", reply.lower())
        self.assertIn("when it's ready", reply.lower())
        self.assertNotIn("available", reply.lower())
        # No date, no price, no number at all.
        self.assertFalse(any(ch.isdigit() for ch in reply), reply)

    def test_amharic_template(self):
        reply = bot.t("paused_services", "am")
        self.assertTrue(reply)
        self.assertNotEqual(reply, bot.t("paused_services", "en"))
        self.assertIn("ቆሟል", reply)
        self.assertFalse(any(ch.isdigit() for ch in reply), reply)

    def test_is_paused_services_request_negatives(self):
        for text in (
            "I want 1k TikTok views",
            "how much are 1000 views",
            "I want to resell",
            "I need support",
            "do you sell followers?",
            "I want premium followers",
            "I want Spotify followers",
            "I want Telegram Premium members",
            "I want Telegram Premium",
            "I want premium views for my video",
        ):
            self.assertFalse(bot.is_paused_services_request(text), text)

    def test_local_intent_routes_paused_not_order(self):
        self.assertEqual(
            bot.local_intent("I want CapCut Pro")["intent"],
            "paused_services",
        )
        self.assertEqual(
            bot.local_intent("I want 1k TikTok views")["intent"], "order"
        )
        # A metric word makes it an order, not a paused ask.
        self.assertEqual(
            bot.local_intent("I want premium followers")["intent"],
            "order",
        )

    async def test_order_message_never_gets_paused_answer(self):
        msg = await self._send(
            "I want 1k TikTok views", intent_of("order"),
            paxyo=TikTokPaxyo(),
        )
        self.assertEqual(len(msg.text_sent), 1)
        self.assertNotIn("paused", msg.text_sent[0].lower())

    async def test_price_question_never_gets_paused_answer(self):
        msg = await self._send(
            "how much are 1000 TikTok views", intent_of("paxyo_info"),
            paxyo=TikTokPaxyo(),
        )
        self.assertEqual(len(msg.text_sent), 1)
        self.assertNotIn("paused", msg.text_sent[0].lower())
        self.assertIn("ETB", msg.text_sent[0])

    async def test_reseller_and_contact_keep_their_answers(self):
        reseller = await self._send_local("I want to resell")
        self.assertEqual(
            reseller.text_sent, [bot.t("reseller_contact", "en")]
        )
        contact = await self._send_local("I need support")
        self.assertEqual(
            contact.text_sent, [bot.t("contact_owner", "en")]
        )

    def test_greeting_and_help_never_mention_paused_services(self):
        for key in ("greeting", "help"):
            for lang in ("en", "am"):
                text = bot.t(key, lang).lower()
                self.assertNotIn("paused", text, key)
                self.assertNotIn("capcut", text, key)
                self.assertNotIn("canva", text, key)


class FlakyReactionsPaxyo(RealReactionsPaxyo):
    """Catalogue fails on the first call, works after — since the
    price fast path (14 Nov 2026) the first call is the fast-path
    price lookup, which fails silently, so the direct price answer
    still finds the price on its own lookup after the classifier
    pre-fetch."""

    def __init__(self):
        self._calls = 0

    async def services(self):
        self._calls += 1
        if self._calls == 1:
            raise RuntimeError("catalogue hiccup")
        return await super().services()


class FlakyTwiceReactionsPaxyo(RealReactionsPaxyo):
    """Catalogue fails on the first TWO calls, works after — the
    fast-path lookup and the classifier pre-fetch both fail, but
    the post-classification direct price answer still finds the
    price on its own lookup, so the reply is the direct price
    (no link ask)."""

    def __init__(self):
        self._calls = 0

    async def services(self):
        self._calls += 1
        if self._calls <= 2:
            raise RuntimeError("catalogue hiccup")
        return await super().services()


class FlakyThriceReactionsPaxyo(RealReactionsPaxyo):
    """Catalogue fails on the first THREE calls, works after — the
    fast-path lookup, the classifier pre-fetch and the direct
    price answer all find nothing, so the order flow must still
    carry the price into the link-asking reply (the link-ask
    safety net)."""

    def __init__(self):
        self._calls = 0

    async def services(self):
        self._calls += 1
        if self._calls <= 3:
            raise RuntimeError("catalogue hiccup")
        return await super().services()


class TestDeterministicPriceFix(unittest.IsolatedAsyncioTestCase):
    """The live bug of 14 Nov 2026: the same message ("I want 👍
    reaction for my telegram channel post how much 1k") got its
    price from Groq at 12:52 and lost it from DeepSeek at 13:16 —
    the price answer used to depend on which AI classified the
    message. Now the price is deterministic code: the price branch
    runs on the detector alone, and a reply that asks for the link
    after a price question always carries the price too."""

    def setUp(self):
        for store in (
            bot.USER_TRAITS, bot.USUAL_SERVICE,
            bot._USUAL_COUNTS, bot._TONE_SIGNALS,
            bot._TRAITS_FROM_SERVER, bot._LAST_TRAITS_SAVE,
            bot.PENDING, bot.PENDING_REFILL, bot.LAST_ORDER, bot.PARTIAL,
            bot.PENDING_RECURRING, bot.RECURRING_DRAFT,
            bot.DEPOSIT_DRAFT, bot.PENDING_DEPOSIT, bot.LAST_DEPOSIT,
            bot.PENDING_BATCH, bot.SPLIT_DRAFT, bot.FASTEST_FALLBACK,
            bot.BUDGET_OPTIONS, bot.SEEN_UPDATES, bot.RECEIPT_OFFER,
            bot.OFF_TOPIC_COUNT, bot.OFFENSE_COUNT, bot.HUMOR_INDEX,
            bot.CANCELLED_DRAFT,
        ):
            store.clear()
        bot.CHAT_HISTORY.clear()
        bot._CHAT_HISTORY_LOADED = False
        self._history_file = os.path.join(
            tempfile.gettempdir(), "paxyo-test-chat-history.json"
        )
        if os.path.exists(self._history_file):
            os.unlink(self._history_file)
        self._history_patch = mock.patch.object(
            bot, "CHAT_HISTORY_FILE", self._history_file
        )
        self._history_patch.start()
        bot._LAST_HISTORY_SAVE = 0.0

    def tearDown(self):
        self._history_patch.stop()
        for store in (
            bot.USER_TRAITS, bot.USUAL_SERVICE,
            bot._USUAL_COUNTS, bot._TONE_SIGNALS,
            bot._TRAITS_FROM_SERVER, bot._LAST_TRAITS_SAVE,
            bot.PENDING, bot.PENDING_REFILL, bot.LAST_ORDER, bot.PARTIAL,
            bot.PENDING_RECURRING, bot.RECURRING_DRAFT,
            bot.DEPOSIT_DRAFT, bot.PENDING_DEPOSIT, bot.LAST_DEPOSIT,
            bot.PENDING_BATCH, bot.SPLIT_DRAFT, bot.FASTEST_FALLBACK,
            bot.BUDGET_OPTIONS, bot.SEEN_UPDATES, bot.RECEIPT_OFFER,
            bot.OFF_TOPIC_COUNT, bot.OFFENSE_COUNT, bot.HUMOR_INDEX,
            bot.CANCELLED_DRAFT,
        ):
            store.clear()
        bot.CHAT_HISTORY.clear()
        bot._CHAT_HISTORY_LOADED = False
        if os.path.exists(self._history_file):
            os.unlink(self._history_file)

    async def _send(self, text, intent, paxyo=None, ai_reply=_UNSET):
        from contextlib import ExitStack
        msg = FakeMessage()
        update = FakeUpdate(msg)
        patches = [
            mock.patch(
                "bot.extract_intent",
                new=mock.AsyncMock(return_value=intent),
            ),
            mock.patch("bot.paxyo", paxyo or FakePaxyo()),
            mock.patch("bot.speak_reply"),
        ]
        if ai_reply is not _UNSET:
            patches.append(mock.patch(
                "bot.ai_generate",
                new=mock.AsyncMock(return_value=ai_reply),
            ))
        with ExitStack() as stack:
            for patch in patches:
                stack.enter_context(patch)
            await bot.handle_order_text(update, None, text)
        return msg

    # (1) the live repro: same message, any intent, price present ----

    async def test_live_message_quotes_price_whatever_the_intent(self):
        # The 13:16 EAT DeepSeek reply was "Got it — 👍 reactions.
        # Send the link to the post and I'll get it going." — the
        # service identified, no price. Mock the AI to that exact
        # price-less wording and classify the message as something
        # the old intent gate did not cover: the deterministic
        # price must win over the AI's wording either way.
        for intent_type in ("how_to_order", "goal", "safety"):
            with self.subTest(intent=intent_type):
                msg = await self._send(
                    "I want 👍 reaction for my telegram channel post how much 1k",
                    intent_of(intent_type, platform="telegram",
                              service_hint="telegram reactions",
                              quantity=1000),
                    paxyo=RealReactionsPaxyo(),
                    ai_reply=(
                        "Got it — 👍 reactions. Send the link to the "
                        "post and I'll get it going."
                    ),
                )
                reply = msg.text_sent[0]
                self.assertIn("Thumbs up 👍", reply)
                self.assertIn("5.46", reply)
                self.assertIn("1,000", reply)
                self.assertNotIn("81.90", reply)
                self.assertNotIn("336.00", reply)
                self.assertNotIn("Bot Start", reply)
                bot.PARTIAL.clear()

    # (2) a different service and quantity ----------------------------

    async def test_other_service_and_quantity_quotes_total(self):
        msg = await self._send(
            "how much is 5000 tiktok likes?",
            intent_of("goal", platform="tiktok",
                      service_hint="tiktok likes", quantity=5000),
            paxyo=TikTokPaxyo(),
        )
        reply = msg.text_sent[0]
        self.assertIn("TikTok Likes", reply)
        self.assertIn("50.00", reply)
        self.assertIn("5,000", reply)
        self.assertNotIn("Please send the link", reply)

    # (3) the price line appears exactly once, unmangled ---------------

    async def test_price_line_appears_exactly_once(self):
        msg = await self._send(
            "I want 👍 reaction for my telegram channel post how much 1k",
            intent_of("order", platform="telegram",
                      service_hint="telegram reactions", quantity=1000),
            paxyo=RealReactionsPaxyo(),
        )
        self.assertEqual(
            msg.text_sent[0],
            "Telegram Reactions + Free Views — Thumbs up 👍: "
            "5.46 ETB for 1,000 (5.46 ETB per 1000).",
        )
        self.assertEqual(msg.text_sent[0].count("5.46 ETB for 1,000"), 1)

    # (4) the price still quotes when the first lookup fails --------
    # (the fast-path lookup fails silently, the classifier
    # pre-fetch succeeds, and the direct price answer still finds
    # the price) ------------------------------------------------------

    async def test_link_ask_reply_carries_price_when_lookup_fails_once(self):
        paxyo = FlakyReactionsPaxyo()
        msg = await self._send(
            "I want 👍 reaction for my telegram channel post how much 1k",
            intent_of("order", platform="telegram",
                      service_hint="telegram reactions", quantity=1000),
            paxyo=paxyo,
        )
        self.assertEqual(paxyo._calls, 3)
        reply = msg.text_sent[0]
        # The direct price answer quotes 5.46 exactly once, even
        # though the first catalogue lookup failed.
        self.assertIn("Thumbs up 👍", reply)
        self.assertIn("5.46 ETB for 1,000", reply)
        self.assertEqual(reply.count("5.46 ETB for 1,000"), 1)
        self.assertNotIn("Please send the link", reply)

    # (5) the direct price still answers when the first TWO lookups
    # fail (fast path + pre-fetch), and the link-asking reply
    # carries the price when the first THREE fail ------------------

    async def test_direct_price_answers_when_lookup_fails_twice(self):
        paxyo = FlakyTwiceReactionsPaxyo()
        msg = await self._send(
            "I want 👍 reaction for my telegram channel post how much 1k",
            intent_of("order", platform="telegram",
                      service_hint="telegram reactions", quantity=1000),
            paxyo=paxyo,
        )
        self.assertEqual(paxyo._calls, 3)
        reply = msg.text_sent[0]
        self.assertIn("Thumbs up 👍", reply)
        self.assertIn("5.46 ETB for 1,000", reply)
        self.assertEqual(reply.count("5.46 ETB for 1,000"), 1)
        self.assertNotIn("Please send the link", reply)

    async def test_link_ask_reply_carries_price_when_lookup_fails_thrice(self):
        paxyo = FlakyThriceReactionsPaxyo()
        msg = await self._send(
            "I want 👍 reaction for my telegram channel post how much 1k",
            intent_of("order", platform="telegram",
                      service_hint="telegram reactions", quantity=1000),
            paxyo=paxyo,
        )
        self.assertEqual(paxyo._calls, 4)
        reply = msg.text_sent[0]
        # The price line is there, once, ahead of the link ask —
        # and the emoji acknowledgement survived intact.
        self.assertIn("Thumbs up 👍", reply)
        self.assertIn("5.46 ETB for 1,000", reply)
        self.assertEqual(reply.count("5.46 ETB for 1,000"), 1)
        self.assertIn("Got it — 👍 reactions", reply)
        self.assertIn("Send the link to the post", reply)


